def audit_pair(qid,vid,finals,control=False):
    folder=HERE/qid/vid;summarypath=next((folder/'tests').glob('*/summary.json'));summary=json.loads(summarypath.read_text(encoding='utf-8-sig'));evidence=summarypath.parent
    binding=json.loads((evidence/'binding.json').read_text());requestbytes=(evidence/'request.json').read_bytes();payload=json.loads(requestbytes)
    design=json.loads((folder/'design.json').read_text());record=json.loads((HERE/qid/'formal_record.json').read_text());expected=design['expected_wrong_answer']
    assert summary['two_completed'] and len(summary['results'])==2
    assert set(payload)=={'model','stream','thinking','messages'}
    assert payload['model']=='mimo-v2.6-flash' and payload['stream'] is False and payload['thinking']=={'type':'disabled'}
    assert len(payload['messages'])==2 and payload['messages'][0]=={'role':'system','content':binding['system_prompt']}
    assert payload['messages'][1]['role']=='user' and len(payload['messages'][1]['content'])==2
    assert payload['messages'][1]['content'][0]=={'type':'text','text':record['question']}
    image_url=payload['messages'][1]['content'][1]['image_url']['url'];assert image_url.startswith('data:image/png;base64,')
    assert base64.b64decode(image_url.split(',',1)[1])==(folder/'candidate.png').read_bytes()
    assert file_hash(folder/'candidate.png')==binding['image_sha256']==summary['image_sha256']
    assert file_hash(folder/'design.json')==binding['design_sha256']==file_hash(evidence/'design_snapshot.json')
    assert file_hash(evidence/'request.json')==binding['request_body_sha256']
    assert canonical_hash(record)==binding['question_record_sha256']
    assert pixel_hash(folder/'candidate.png')==binding['pixel_sha256']
    if not control:
        render=json.loads((folder/'render_check.json').read_text());assert render['png_sha256']==binding['image_sha256'] and render['design_sha256']==binding['design_sha256']
        assert render['baseline_pixel_match'] and render['schema_normalized'] and render['two_byte_identical_redraws']
    else:assert (folder/'candidate.png').read_bytes()==(ROOT/'PlaneGeometry/image'/f'{qid}.png').read_bytes()
    runs=[]
    for i,(job,final) in enumerate(zip(summary['results'],finals),1):
        raw=evidence/f'run_{i:02d}_response.json';started=json.loads((evidence/f'run_{i:02d}_started.json').read_text());saved=json.loads((evidence/f'run_{i:02d}.json').read_text())
        assert job['status']==saved['status']=='completed' and file_hash(raw)==job['response_sha256']
        assert started['request_body_sha256']==job['request_body_sha256']==binding['request_body_sha256']
        assert started['image_sha256']==job['image_sha256']==binding['image_sha256']
        assert started['design_sha256']==job['design_sha256']==binding['design_sha256']
        runs.append({'run_index':i,'status':'completed','complete_answer_manually_read':True,'manual_final_answer':final,'predeclared_target_hit':final==expected,'final_matches_formal_answer':final==record['answer'],'answer_text_path':relative(evidence/f'run_{i:02d}.json'),'raw_response_path':relative(raw),'raw_response_sha256':file_hash(raw),'answer_sha256':hashlib.sha256(job['answer'].encode('utf-8')).hexdigest()})
    result={'question_id':qid,'variant_id':vid,'kind':'original_control' if control else 'candidate','expected_wrong_answer_before_both_calls':expected,'formal_correct_answer':record['answer'],'manual_final_answers':finals,'two_target_hits':all(f==expected for f in finals),'runs':runs,'binding_path':relative(evidence/'binding.json'),'summary_path':relative(summarypath),'request_path':relative(evidence/'request.json'),'same_frozen_png_sha256':binding['image_sha256'],'same_immutable_design_sha256':binding['design_sha256'],'same_request_body_sha256':binding['request_body_sha256'],'no_retries':True,'solver_input_gate':'Exact only formalquestion plus this frozenPNG plus unchanged referencesystem. No design/preset/correctanswer/intent/parameters/originalcomparison included.'}
    manual.append(result);audits.append({'question_id':qid,'variant_id':vid,'all_exact_bindings_pass':True,**{k:result[k] for k in ['kind','binding_path','same_frozen_png_sha256','same_immutable_design_sha256','same_request_body_sha256']}})
    if not control:
        candidate_records.append({**result,'candidate_directory':relative(folder),'candidate_path':relative(folder/'candidate.png'),'plugin_path':relative(folder/'plugin.json'),'design_path':relative(folder/'design.json'),'fresh_context_path':relative(folder/'context.json'),'render_check_path':relative(folder/'render_check.json'),'primary_review_path':relative(folder/'primary_review.json'),'status':'POSSIBLE_TWO_HIT_REQUIRES_NEW_PARENT_INDEPENDENT_REVIEW' if result['two_target_hits'] else 'TESTED_PRESET_MISS_DO_NOT_RETEST_IDENTICAL_IMAGE','mechanism':design['mechanism'],'marker_roles':design['marker_roles'],'mathematical_proof':design['mathematical_solution']})
